import re
R='src/main/resources/officefloor/rest/api/sheets/{sheetId}/'
def ins(f, after_step, new_steps):
    p=R+f; s=open(p).read()
    # find "after_step:\n ... next: X" and redirect
    m=re.search(r'^'+after_step+r':\n(?:  .*\n)*?  next: (\S+)\n', s, re.M)
    nxt=m.group(1)
    names=[n for n,_ in new_steps]
    block=''
    for i,(n,cls) in enumerate(new_steps):
        block+=f"{n}:\n  class: net.officefloor.hq.app.claim.{cls}\n  govern: [ transaction ]\n  next: {names[i+1] if i+1<len(names) else nxt}\n"
    old=m.group(0)
    s=s.replace(old, old[:-len('  next: '+nxt+'\n')]+'  next: '+names[0]+'\n'+block,1)
    open(p,'w').write(s)
